async def go():
    async with sm.AsyncSessionLocal() as db:
        rows = []
        for applier in sorted(_PR_BY_APPLIER):
            email = M.resolve_user_email(applier)
            if not email:
                continue
            row = (await db.execute(text("SELECT id::text, full_name FROM users WHERE lower(email)=:e"), {"e": email.lower()})).first()
            if row is None:
                continue  # expected user not in this DB — can't judge a mismatch
            uid, expected_name = row[0], row[1]
            nums = _PR_BY_APPLIER[applier]
            res = (await db.execute(text(
                "SELECT (SELECT full_name FROM users WHERE id=pr.created_by) AS cur, count(*) "
                "FROM purchase_requests pr WHERE pr.number = ANY(:nums) "
                "AND pr.created_by <> CAST(:uid AS uuid) "
                "GROUP BY 1 ORDER BY 2 DESC"), {"nums": nums, "uid": uid})).all()
            mismatched = sum(c for _, c in res)
            in_db = (await db.execute(text("SELECT count(*) FROM purchase_requests WHERE number = ANY(:nums)"), {"nums": nums})).scalar()
            if mismatched:
                rows.append((applier, expected_name or email, in_db, mismatched, res[:3]))
        rows.sort(key=lambda r: -r[3])
        total = 0
        for applier, expected, in_db, mism, sample in rows:
            total += mism
            print(f"Applier={applier!r} -> should be {expected!r}: {mism}/{in_db} PRs on the WRONG user")
            for cur, c in sample:
                print(f"    currently {cur!r}: {c}")
        print("")
        print(f"TOTAL mismatched PRs: {total} (read-only, nothing changed)")


if __name__ == "__main__":
    asyncio.run(go())
